}

export interface ILeavePolicyService {
  getPolicyForLeaveType(leaveType: LeaveType): Promise<LeavePolicy | null>;
  validateEntitlement(employeeId: string, leaveType: LeaveType, requestedDays: number): Promise<boolean>;
}

